(()=>{let a=null;self.onmessage=async b=>{let{type:c,id:d,...e}=b.data;try{switch(c){case"init":a=new SippClient({backend:e.config.backend}),await a.initialize(),self.postMessage({type:"ready",id:d});break;case"loadModel":if(!a)throw Error("Client not initialized");await a.loadModel(e.path,{format:e.format,onProgress:a=>{self.postMessage({type:"progress",id:d,progress:a})}}),self.postMessage({type:"modelLoaded",id:d});break;case"generate":if(!a)throw Error("Client not initialized");let{messages:b,options:f}=e,g="";await a.generate(b,{maxTokens:f.maxTokens,temperature:f.temperature,topP:f.topP,stream:!0,onToken:a=>{g+=a,self.postMessage({type:"token",id:d,token:a})}}),self.postMessage({type:"complete",id:d,text:g});break;case"unloadModel":if(!a)throw Error("Client not initialized");await a.unloadModel(),self.postMessage({type:"modelUnloaded",id:d});break;default:throw Error(`Unknown message type: ${c}`)}}catch(a){self.postMessage({type:"error",id:d,error:a.message})}},module.exports={}})();